def has_subgraph_of_weight_k(graph, k):
    """
    Checks if a graph G contains a subgraph of weight k.

    Args:
        graph: A dictionary representing the graph where keys are vertices
               and values are lists of adjacent vertices.
        k: The target weight for the subgraph.

    Returns:
        True if the graph contains a subgraph of weight k, False otherwise.
    """

    def is_subgraph(subgraph_nodes, weight):
        """
        Checks if a subgraph of the given nodes has a weight of k.
        """
        for u in subgraph_nodes:
            for v in subgraph_nodes:
                if u!= v:
                    if graph[u][v]!= weight:
                        return False
        return True

    def find_subgraph(nodes, weight):
        """
        Finds a subgraph of the given nodes with the specified weight.
        """
        if not nodes:
            return []

        subgraph = {}
        for node in nodes:
            subgraph[node] = []
            for neighbor in graph[node]:
                if neighbor in nodes:
                    subgraph[node].append(neighbor)

        return subgraph

    # Check if the graph is empty
    if not graph:
        return False

    # Check if the target weight is valid
    if k < 0:
        return False

    # Check if the graph contains a subgraph of weight k
    for nodes in graph.values():
        if is_subgraph(nodes, k):
            return True

    return False
